import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.commonSettings().getSettings(Map.of("type", "customer_registration_field", "config_key", "abn_placeholder"));
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("settings");
for (Object row : (List<?>) settings.get("customer_registration_field")) {
    Map<?, ?> setting = (Map<?, ?>) row;
    System.out.println(setting.get("config_key") + " " + setting.get("value"));
}

